import os
import json
import boto3
from botocore.exceptions import BotoCoreError, ClientError


class SecretFetchError(Exception):
    pass


def fetch_database_connection_secret(secret_name: str, region_name: str | None = None) -> dict:
    region = region_name or os.getenv("AWS_REGION") or os.getenv("AWS_DEFAULT_REGION")
    if not region:
        raise SecretFetchError("AWS region is required via argument, AWS_REGION, or AWS_DEFAULT_REGION")

    client = boto3.client("secretsmanager", region_name=region)

    try:
        response = client.get_secret_value(SecretId=secret_name)
    except (BotoCoreError, ClientError) as e:
        raise SecretFetchError(f"Failed to fetch secret from AWS Secrets Manager: {e}") from e

    secret_string = response.get("SecretString")
    if secret_string is None:
        raise SecretFetchError("Secret is binary; expected a JSON string secret")

    try:
        secret = json.loads(secret_string)
    except json.JSONDecodeError as e:
        raise SecretFetchError("SecretString is not valid JSON") from e

    required_keys = {"host", "port", "username", "password", "database"}
    missing = required_keys - secret.keys()
    if missing:
        raise SecretFetchError(f"Missing required secret fields: {', '.join(sorted(missing))}")

    return {
        "host": secret["host"],
        "port": int(secret["port"]),
        "username": secret["username"],
        "password": secret["password"],
        "database": secret["database"],
    }
